using MessagePack.Formatters;

public class A5_F4_DeclarativeKeysTests(ITestOutputHelper logger)
{
    private static readonly MessagePackSerializerOptions SerializerOptions = MessagePackSerializerOptions.Standard;

    [Fact]
    public void A5_F4_TypeWithoutAttributes_RoundtripsThroughGeneratedResolver()
    {
        var value = new PlainPoint { X = 3, Y = 7, Transient = "skip" };

        byte[] serialized = MessagePackSerializer.Serialize(value, SerializerOptions);
        logger.WriteLine(MessagePackSerializer.ConvertToJson(serialized, SerializerOptions));
        PlainPoint after = MessagePackSerializer.Deserialize<PlainPoint>(serialized, SerializerOptions);

        Assert.Equal(value.X, after.X);
        Assert.Equal(value.Y, after.Y);
    }

    [Fact]
    public void A5_F4_FormatterIsAvailableForTypeWithoutAttributes()
    {
        IMessagePackFormatter<PlainPoint>? formatter = null;
        Exception? ex = Record.Exception(() => formatter = SerializerOptions.Resolver.GetFormatterWithVerify<PlainPoint>());
        Assert.Null(ex);
        Assert.NotNull(formatter);
    }

    /// <summary>
    /// A type that carries no MessagePack attributes at all.
    /// </summary>
    public class PlainPoint
    {
        public int X { get; set; }

        public int Y { get; set; }

        public string? Transient { get; set; }
    }
}
